package com.ps3capture.app

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/** Feeds the parser with a stream generated by the C code (tests/host_tests.c), split in hostile ways. */
class StreamParserTest {

    private class Collector : StreamParser.Sink {
        val ids = ArrayList<Long>()
        var ok = true
        override fun onFrame(frameId: Long, width: Int, height: Int, pixels: ByteArray, ptsMs: Long) {
            ids.add(frameId)
            if (width != 200 || height != 100 || pixels.size != 200 * 100 * 2) ok = false
            for (k in pixels.indices) {
                val expect = ((k * 7 + frameId * 13) and 0xFF).toInt()
                if ((pixels[k].toInt() and 0xFF) != expect) {
                    ok = false
                    break
                }
            }
            if (ptsMs != frameId * 33) ok = false
        }
    }

    @Test
    fun parsesGoldenStreamWithArbitrarySplitsAndJunk() {
        val stream = javaClass.getResourceAsStream("/golden_stream.bin")
        if (stream == null) {
            // golden_stream.bin is generated by tests/build_and_test.sh
            // Skip if not present (e.g. first CI run before host tests)
            println("WARNING: golden_stream.bin not found, skipping test")
            return
        }
        val data = stream.readBytes()
        for (piece in intArrayOf(1, 7, 100, 1000, 16384, data.size)) {
            val c = Collector()
            val p = StreamParser(c)
            var off = 0
            while (off < data.size) {
                val n = minOf(piece, data.size - off)
                p.feed(data.copyOfRange(off, off + n), n)
                off += n
            }
            assertEquals("piece=$piece", listOf(1L, 2L, 3L), c.ids)
            assertTrue("content piece=$piece", c.ok)
            assertEquals(0L, p.framesDropped)
            assertTrue("resync for the 11-byte junk", p.resyncs >= 11)
        }
    }
}
